class Hero:
    MAX = 10

    def __init__(self, name):
        self.name, self.health, self.potions = name, self.MAX, 2

    def hit(self, damage):
        self.health = max(0, self.health - damage)

    def drink(self):
        if not self.potions:
            return
        self.potions -= 1
        self.health = min(self.MAX, self.health + 5)

    def status(self):
        return f"{self.name} {self.health}/{self.MAX} potions: {self.potions}"

hero = Hero(input())
while (command := input()) != "end":
    if command == "hit":
        hero.hit(int(input()))
    else:
        hero.drink()
    print(hero.status())

class Hero:
    def __init__(self, name, health=10, potions=2):
        self.name = name
        self.health = health
        self.potions = potions

    def hit(self, damage):
        self.health -= damage
        if self.health < 0:
            self.health = 0

    def drink(self):
        if self.potions == 0:
            return
        self.potions -= 1
        self.health += 5
        if self.health > 10:
            self.health = 10

    def status(self):
        return self.name + " " + str(self.health) + "/10 potions: " + str(self.potions)

hero = Hero(input())
actions = {"hit": lambda: hero.hit(int(input())), "drink": hero.drink}
command = input()
while command != "end":
    actions[command]()
    print(hero.status())
    command = input()
